class Dog:
    def __init__(self, name, age=1):
        self.name = name        # instance attributes
        self.age = age

    def bark(self):
        return f"{self.name} says woof"

rex = Dog("Rex", 3)
print(rex.bark())       # Rex says woof
print(rex.age)          # 3
print(rex)              # <__main__.Dog object at 0x...> — no __repr__ yet

